const responses = $input.all();
const urlsList = $('Build URLs List').all();
const results = [];

for (let i = 0; i < responses.length; i++) {
  const url = urlsList[i].json.inspect_url;
  const r = responses[i].json?.inspectionResult?.indexStatusResult || {};
  const cov = r.coverageState || 'unknown';
  results.push({
    url,
    coverage_state: cov,
    verdict: r.verdict || '',
    google_canonical: r.googleCanonical || '',
    user_canonical: r.userCanonical || '',
    canonical_mismatch: !!(r.googleCanonical && r.userCanonical && r.googleCanonical !== r.userCanonical),
    last_crawl_time: r.lastCrawlTime || '',
    page_fetch_state: r.pageFetchState || '',
    robots_state: r.robotsTxtState || '',
    indexing_state: r.indexingState || ''
  });
}

// Classify
const buckets = {
  indexed_no_traffic: [],
  crawled_not_indexed: [],
  discovered_not_indexed: [],
  duplicate_canonical: [],
  excluded_noindex: [],
  other: []
};

for (const r of results) {
  const c = (r.coverage_state || '').toLowerCase();
  if (c.includes('submitted and indexed') || c.includes('indexed, not submitted')) {
    buckets.indexed_no_traffic.push(r);
  } else if (c.includes('crawled') && c.includes('not indexed')) {
    buckets.crawled_not_indexed.push(r);
  } else if (c.includes('discovered') && c.includes('not indexed')) {
    buckets.discovered_not_indexed.push(r);
  } else if (c.includes('duplicate') || (r.canonical_mismatch && c.includes('alternate'))) {
    buckets.duplicate_canonical.push(r);
  } else if (c.includes('noindex')) {
    buckets.excluded_noindex.push(r);
  } else {
    buckets.other.push(r);
  }
}

// Build sheet rows
const auditDate = new Date().toISOString().split('T')[0];
const sheetRows = results.map(r => [
  auditDate,
  r.url,
  r.coverage_state,
  r.verdict,
  r.google_canonical,
  r.user_canonical,
  r.canonical_mismatch ? 'YES' : 'no',
  r.last_crawl_time,
  r.page_fetch_state
]);

// Build telegram
const slug = (u) => u.replace('https://bigotesfelinos.com', '').slice(0, 60);
const lines = [];
lines.push('📋 *Coverage Audit* — ' + auditDate);
lines.push('Total: ' + results.length + ' URLs');
lines.push('');

function section(emoji, title, list, action, withCanonical) {
  if (list.length === 0) return;
  lines.push(emoji + ' *' + title + '* (' + list.length + ')');
  lines.push('   _' + action + '_');
  for (const r of list.slice(0, 10)) {
    let line = '   • ' + slug(r.url);
    if (withCanonical && r.google_canonical && r.canonical_mismatch) {
      line += ' → ' + slug(r.google_canonical);
    }
    lines.push(line);
  }
  if (list.length > 10) lines.push('   _(+' + (list.length - 10) + ' más)_');
  lines.push('');
}

section('✅', 'Indexed sin tráfico', buckets.indexed_no_traffic, 'Re-optimizar con WF-Util o consolidar', false);
section('🔴', 'Crawled, NOT indexed', buckets.crawled_not_indexed, 'Calidad rechazada — re-optimizar agresivo o redirect 301', false);
section('🔴', 'Duplicate / canonical mismatch', buckets.duplicate_canonical, 'Canibalización confirmada — redirect 301 al ganador', true);
section('⚠️', 'Discovered, NOT indexed', buckets.discovered_not_indexed, 'Solicitar indexación manual + reforzar enlaces internos', false);
section('🚫', 'Excluded by noindex', buckets.excluded_noindex, 'Validar si es intencional', false);
section('❓', 'Otros / sin clasificar', buckets.other, 'Revisar manualmente', false);

const telegram_message = lines.join('\n');
const sheet_payload = JSON.stringify({ values: sheetRows });

return [{
  json: {
    audit_date: auditDate,
    total: results.length,
    counts: {
      indexed_no_traffic: buckets.indexed_no_traffic.length,
      crawled_not_indexed: buckets.crawled_not_indexed.length,
      discovered_not_indexed: buckets.discovered_not_indexed.length,
      duplicate_canonical: buckets.duplicate_canonical.length,
      excluded_noindex: buckets.excluded_noindex.length,
      other: buckets.other.length
    },
    telegram_message,
    sheet_payload,
    results
  }
}];
